"""
Conteúdo dos atendimentos do "Simulador de Suporte" (jogo de treinamento
na tela Início, irmão do Simulador de Campo — só que aqui o aluno atende
o cliente por chat, não vai até o endereço).

Cada atendimento tem uma ou mais decisões (fala do cliente + 3 respostas
possíveis, uma "correta" — tecnicamente certa E adequada ao tom do
cliente). Os primeiros 50 atendimentos têm 4 decisões cada (uma conversa
completa); o segundo lote (a partir de ATD-17510) tem 1 decisão só —
chamados mais curtos e diretos, no mesmo estilo dos cenários reais
recebidos da operação. jogo_suporte.py já lida com essa variação (usa
len(atendimento["decisoes"]) em vez de um número fixo). Cada resposta
também tem um humor_delta: o quanto o humor do cliente sobe ou desce
depois dela. O humor começa em humor_inicial (varia por atendimento,
conforme o quão alterado o cliente já chega) e é mostrado como um medidor
visível na tela, igual ao medidor óptico do Simulador de Campo.

A lógica do jogo em si fica em webapp/services/jogo_suporte.py — aqui só
o conteúdo. Situações reais de atendimento ao público: sem internet,
internet lenta, financeiro/2ª via, cancelamento, streaming, portabilidade,
mudança de endereço, senha do app, atraso de instalação, configuração,
jogos/CGNAT.
"""

